WITH base AS (SELECT *, CAST(revenue AS INT) AS revenue_int, LAST_DAY(sale_date) AS sale_date_month_end FROM store_sales WHERE store_id = 3), matched_keys AS (SELECT id, store_id FROM base EXCEPT DISTINCT SELECT id, store_id FROM store_sales WHERE sale_date BETWEEN '2023-06-12' AND '2024-07-20'), reconciled AS (SELECT s.* FROM base s JOIN matched_keys k ON s.id = k.id AND s.store_id = k.store_id), with_windows AS (SELECT id, store_id, product_id, sale_date, units, revenue, revenue_int, sale_date_month_end, MIN(revenue_int) OVER (PARTITION BY store_id, product_id) AS store_id_min_revenue_int, DENSE_RANK() OVER (ORDER BY revenue_int DESC NULLS FIRST) AS revenue_int_dense_rank, SUM(units) OVER (PARTITION BY product_id) AS product_id_sum_units FROM reconciled), with_windows_store_sales AS (SELECT id, store_id, product_id, sale_date, units, revenue, revenue_int, sale_date_month_end, store_id_min_revenue_int, revenue_int_dense_rank, product_id_sum_units, SUM(revenue) OVER w_grp AS store_id_sum_revenue, DENSE_RANK() OVER (PARTITION BY product_id ORDER BY revenue_int DESC NULLS FIRST) AS revenue_int_dense_rank_2 FROM with_windows WINDOW w_grp AS (PARTITION BY store_id)), metrics AS (SELECT id, store_id, product_id, sale_date, units, revenue, revenue_int, sale_date_month_end, store_id_min_revenue_int, revenue_int_dense_rank, product_id_sum_units, store_id_sum_revenue, revenue_int_dense_rank_2, ROUND(store_id_sum_revenue / SUM(store_id_sum_revenue) OVER (PARTITION BY store_id), 4) AS store_id_sum_revenue_share, DENSE_RANK() OVER (PARTITION BY product_id, store_id ORDER BY store_id_min_revenue_int DESC NULLS FIRST) AS store_id_min_revenue_int_dense_rank FROM with_windows_store_sales), enriched AS (SELECT a.*, b.cost, b.category FROM metrics a LEFT JOIN products b ON a.product_id = b.id) SELECT s.id, s.store_id, s.sale_date, s.units, s.revenue, s.revenue_int, s.sale_date_month_end, s.store_id_min_revenue_int, s.revenue_int_dense_rank, (SELECT MAX(i2.quantity) FROM inventory i2 WHERE i2.store_id = s.store_id) AS max_inventory_quantity FROM enriched s ORDER BY store_id NULLS FIRST, units DESC;
